type Store struct {
	pool *pgxpool.Pool
	log  *slog.Logger
	cfg  config.PostgresConfig
}

// New abre el pool y verifica conectividad.
func New(ctx context.Context, cfg config.PostgresConfig, log *slog.Logger) (*Store, error) {
	if log == nil {
		log = slog.Default()
	}

	poolCfg, err := pgxpool.ParseConfig(cfg.DSN)
	if err != nil {
		return nil, fmt.Errorf("storage: parse dsn: %w", err)
	}

	poolCfg.MaxConns = cfg.MaxConns
	poolCfg.MinConns = cfg.MinConns
	poolCfg.MaxConnLifetime = cfg.MaxConnLifetime
	poolCfg.MaxConnIdleTime = cfg.MaxConnIdleTime
	poolCfg.ConnConfig.ConnectTimeout = cfg.ConnectTimeout

	pool, err := pgxpool.NewWithConfig(ctx, poolCfg)
	if err != nil {
		return nil, fmt.Errorf("storage: new pool: %w", err)
	}

	pingCtx, cancel := context.WithTimeout(ctx, cfg.ConnectTimeout)
	defer cancel()

	if err := pool.Ping(pingCtx); err != nil {
		pool.Close()
		return nil, fmt.Errorf("storage: ping: %w", err)
	}

	log.Info("postgres conectado",
		"max_conns", cfg.MaxConns,
		"min_conns", cfg.MinConns,
		"connect_timeout", cfg.ConnectTimeout,
	)

	return &Store{pool: pool, log: log.With("component", "storage"), cfg: cfg}, nil
}

// Pool expone el pool subyacente.
func (s *Store) Pool() *pgxpool.Pool { return s.pool }

// Health para readiness probes.
func (s *Store) Health(ctx context.Context) error {
	probeCtx, cancel := context.WithTimeout(ctx, 2*time.Second)
	defer cancel()
	return s.pool.Ping(probeCtx)
}

// Close cierra el pool.
func (s *Store) Close() {
	s.log.Info("postgres cerrando")
	s.pool.Close()
}

